import { bls12_381 } from '@noble/curves/bls12-381.js'
import { describe, expect, it } from 'vitest'
import { decrypt, encrypt, identityPoint, parseCiphertext, ShutterCryptoError, verifyDecryptionKey } from '../src/index.js'
import { keyper } from './keyper.js'
import { toHex } from '../src/bytes.js'
import vectors from './vectors.json'

// Shutter's own vectors (shutter-sdk tests/test-data.json, generated by shcrypto in Go).
type Vector = { name: string; test_data: Record<string, string> }

describe("Shutter's own vectors", () => {
  for (const v of vectors as Vector[]) {
    const d = v.test_data
    it(v.name, () => {
      if (v.name.includes('encryption')) expect(toHex(encrypt({ message: d.message!, identity: d.epoch_id!, eonKey: d.eon_public_key!, sigma: d.sigma! }))).toBe(d.expected)
      else expect(toHex(decrypt(d.cipher!, d.epoch_secret_key!))).toBe(d.expected)
    })
  }
})

describe('encrypt / decrypt', () => {
  const k = keyper()
  const identity = '0x3f27e60a172f2d20232da5042600cafeecd38ce864b60142942547aa9920979c'

  it('round-trips messages of every padding length, empty included', () => {
    for (const n of [0, 1, 31, 32, 33, 64, 200]) {
      const m = new Uint8Array(n).map((_, i) => (i * 7) & 0xff)
      const ct = encrypt({ message: m, identity, eonKey: k.eonKey })
      expect(ct.length).toBe(129 + 32 * (Math.floor(n / 32) + 1))
      expect(decrypt(ct, k.keyFor(identity))).toEqual(m)
    }
  })

  it('a fresh sigma every time: the same message encrypts differently', () => {
    const a = encrypt({ message: '0x01', identity, eonKey: k.eonKey })
    const b = encrypt({ message: '0x01', identity, eonKey: k.eonKey })
    expect(toHex(a)).not.toBe(toHex(b))
  })

  it('the key of another identity, another keyper set, or a changed ciphertext does not open it', () => {
    const ct = encrypt({ message: '0xdeadbeef', identity, eonKey: k.eonKey })
    const other = '0x' + '11'.repeat(32)
    expect(() => decrypt(ct, k.keyFor(other))).toThrow(ShutterCryptoError)
    expect(() => decrypt(ct, keyper(42n).keyFor(identity))).toThrow(ShutterCryptoError)
    for (const at of [140, ct.length - 1, 100]) {
      const bad = ct.slice(); bad[at]! ^= 1
      expect(() => decrypt(bad, k.keyFor(identity)), `byte ${at}`).toThrow(ShutterCryptoError)
    }
  })

  it('verifies a decryption key by pairing', () => {
    expect(verifyDecryptionKey(k.keyFor(identity), identity, k.eonKey)).toBe(true)
    expect(verifyDecryptionKey(keyper(7n).keyFor(identity), identity, k.eonKey)).toBe(false)
    expect(verifyDecryptionKey(k.keyFor('0x' + '22'.repeat(32)), identity, k.eonKey)).toBe(false)
  })

  it('refuses malformed input: version, length, points, sigma', () => {
    const ct = encrypt({ message: '0x00', identity, eonKey: k.eonKey })
    expect(() => parseCiphertext(Uint8Array.of(2, ...ct.slice(1)))).toThrow(/version/)
    expect(() => parseCiphertext(ct.slice(0, 150))).toThrow(/length/)
    expect(() => encrypt({ message: '0x00', identity, eonKey: '0x' + '00'.repeat(96) })).toThrow(/G2 point/)
    expect(() => decrypt(ct, '0x' + 'ab'.repeat(48))).toThrow(/G1 point/)
    expect(() => encrypt({ message: '0x00', identity, eonKey: k.eonKey, sigma: '0x01' })).toThrow(/sigma/)
    expect(() => encrypt({ message: 'not hex', identity, eonKey: k.eonKey })).toThrow(/hex/)
  })
})
